// 실제 가계부 CSV(5건)를 그대로 파싱해서 초기 지출 데이터로 사용한다.
// (Lorem ipsum이나 임의 데이터가 아니라 data/sample-expenses.csv의 내용과 동일)
export const SAMPLE_EXPENSES_CSV = `일차,항목명,카테고리,금액,통화,통화 당 원화,원화 환산,장소,나만보기 비용,결제한 사람,결제한 사람 수,나눠 낼 사람,나눠 낼 사람 수
1,그랩 공항 -> 더 마하타,교통,101500,IDR,0.092,9338,더 마하타,N,조병건,1,"신수빈,조병건",2
1,The Athena Spa,스파,550000,IDR,0.092,50600,The Athena Spa,N,조병건,1,"신수빈,조병건",2
1,The Athena Spa 팁,기타,100000,IDR,0.092,9200,The Athena Spa,N,조병건,1,"신수빈,조병건",2
1,BELLA ITALIA,식사,800976,IDR,0.092,73690,BELLA ITALIA,N,조병건,1,"신수빈,조병건",2
1,편의점 물,식사,15000,IDR,0.092,1380,편의점,N,조병건,1,"신수빈,조병건",2
`;

export function buildSampleExpenses() {
  const travelerNames = sampleTravelers.map((t) => t.name);
  const { drafts } = parseTripleExpensesCsv(SAMPLE_EXPENSES_CSV, SAMPLE_TRIP_ID, travelerNames);
  // 장소명이 일정 항목 이름과 일치하면 자동으로 연결한다 (섹션 9: 일정 + 가계부 연결)
  return drafts.map(({ expense }) => {
    const linked = sampleSchedule.find(
      (s) => expense.place && s.name.includes(expense.place)
    );
    return {
      ...expense,
      source: "csv" as const,
      scheduleItemId: linked?.id,
    };
  });
}

