export function buildOkinawaExpenses() {
  const travelerNames = okinawaTravelers.map((t) => t.name);
  const { drafts } = parseTripleExpensesCsv(OKINAWA_EXPENSES_CSV, OKINAWA_TRIP_ID, travelerNames);
  return drafts.map(({ expense }) => ({ ...expense, source: "csv" as const }));
}
